const rl=require('node:readline').createInterface({input:process.stdin});rl.on('line',line=>{let m;try{m=JSON.parse(line)}catch{return}if(m.id===undefined)return;let result;if(m.method==='initialize')result={protocolVersion:m.params.protocolVersion,serverInfo:{name:'fixture',version:"0.2.5"},capabilities:{tools:{},resources:{}}};else if(m.method==='tools/list')result={tools:[]};else if(m.method==='resources/list')result={resources:[]};else if(m.method==='prompts/list')result={prompts:[]};else return;process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:m.id,result})+'
')});